on conflict (term_type, term_key) do update
set label_ko = excluded.label_ko,
    label_en = excluded.label_en,
    synonyms = excluded.synonyms,
    parent_term_key = excluded.parent_term_key,
    applicable_sections = excluded.applicable_sections,
    metadata = excluded.metadata,
    taxonomy_version = excluded.taxonomy_version,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active,
    updated_at = now();

create temporary table merged_region (old_key text primary key, new_key text not null) on commit drop;
insert into merged_region (old_key, new_key) values
    ('fr_hautes_cotes_de_nuits', 'fr_bourgogne_hautes_cotes_de_nuits'),
    ('fr_cotes_du_luberon', 'fr_luberon'),
    ('it_sardegna_sardinia', 'it_sardegna'),
    ('it_brunello_di_montalcino', 'it_montalcino'),
    ('de_mosel_saar_ruwer', 'de_mosel'),
    ('pt_porto', 'pt_douro'),
    ('pt_porto_e_douro', 'pt_douro'),
    ('pt_minho', 'pt_vinho_verde'),
    ('hu_tokaj_hegyalja', 'hu_tokaji'),
    ('ar_cafayate_valley', 'ar_cafayate'),
    ('es_', 'es_extremadura'),
    ('us_willakenzie_estate', 'us_yamhill_carlton'),
    ('us_los_carneros_ava', 'us_los_carneros');

update public.alcohol_items as item
   set region_key = merged.new_key
  from merged_region as merged
 where item.region_key = merged.old_key;

-- A member who saved both names keeps the one row.
delete from public.user_saved_terms as saved
 using merged_region as merged
 where saved.term_key = 'region:' || merged.old_key
   and exists (
     select 1 from public.user_saved_terms as kept
      where kept.user_id = saved.user_id
        and kept.term_key = 'region:' || merged.new_key
   );
-- Two rows that went to the same place (포르토 and 포르투 에 도우루) leave one.
delete from public.user_saved_terms as saved
 using merged_region as merged
 where saved.term_key = 'region:' || merged.old_key
   and exists (
     select 1 from public.user_saved_terms as other
       join merged_region as other_merged on other.term_key = 'region:' || other_merged.old_key
      where other.user_id = saved.user_id
        and other_merged.new_key = merged.new_key
        and other_merged.old_key < merged.old_key
   );
update public.user_saved_terms as saved
   set term_key = 'region:' || merged.new_key
  from merged_region as merged
 where saved.term_key = 'region:' || merged.old_key;

-- Every region row written above carries this transaction's now(); what is
-- left is no longer in the dictionary's projection.
delete from public.catalog_taxonomy
 where term_type = 'region'
   and updated_at < now();

commit;
